function currentStreak(habit, today = new Date()) {
  let streak = 0;
  let cursor = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  if (!habit.done[dateKey(cursor)]) {
    cursor.setDate(cursor.getDate() - 1); // today not done yet, streak still alive from yesterday
  }
  while (habit.done[dateKey(cursor)]) {
    streak++;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
}
```

