    refs.name.textContent = habit.name;
    refs.deleteBtn.setAttribute('aria-label', 'Delete habit: ' + habit.name);

    var streak = currentStreak(habit, today);
    refs.streak.textContent = streak === 1 ? '1 day streak' : streak + ' day streak';

    var best = longestStreak(habit);
    refs.best.textContent = best > 0 ? 'Best ' + best : 'No history yet';

    var week = doneInLastDays(habit, WEEK, today);
    refs.week.textContent = week + '/' + WEEK + ' this week';

    // 7 day grid
    refs.days.textContent = '';
    lastNDays(WEEK, today).forEach(function (day) {
