  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function buildCard(habit) {
    var root = templateEl.content.firstElementChild.cloneNode(true);
    var refs = {
      root: root,
      name: root.querySelector('[data-role="name"]'),
      streak: root.querySelector('[data-role="streak"]'),
      best: root.querySelector('[data-role="best"]'),
      week: root.querySelector('[data-role="week"]'),
      days: root.querySelector('[data-role="days"]'),
      todayBtn: root.querySelector('[data-role="today-btn"]'),
      deleteBtn: root.querySelector('[data-action="delete"]')
    };
    root.dataset.habitId = habit.id;
    refs.deleteBtn.title = 'Delete habit';
    cards[habit.id] = refs;
    return root;
  }

  function updateCard(habit) {
    var refs = cards[habit.id];
    if (!refs) return;

    var today = startOfDay(new Date());
    var todayKey = dateKey(today);
    var doneToday = !!habit.done[todayKey];

    refs.name.textContent = habit.name;
    refs.deleteBtn.setAttribute('aria-label', 'Delete habit: ' + habit.name);
    refs.root.classList.toggle('is-done', doneToday);

    var streak = currentStreak(habit, today);
    refs.streak.textContent = streak === 1 ? '1 day streak' : streak + ' day streak';

    var best = longestStreak(habit);
    refs.best.textContent = best > 0 ? 'Best ' + best : 'No history yet';

    refs.week.textContent = doneInLastDays(habit, WEEK, today) + '/' + WEEK + ' this week';

    refs.days.textContent = '';
    lastNDays(WEEK, today).forEach(function (day) {
      var key = dateKey(day);
      var done = !!habit.done[key];
      var isToday = key === todayKey;

      var cell = el('button', 'day');
      cell.type = 'button';
      cell.dataset.action = 'toggle-day';
      cell.dataset.date = key;
      cell.setAttribute('aria-pressed', done ? 'true' : 'false');
      cell.setAttribute('aria-label', formatShort(day) + (isToday ? ' (today)' : '') +
        ' \u2014 ' + (done ? 'done, tap to undo' : 'not done, tap to mark done'));
      if (done) cell.classList.add('is-done');
      if (isToday) cell.classList.add('is-today');

      cell.appendChild(el('span', 'day__dow', weekdayNarrow(day)));
      cell.appendChild(el('span', 'day__num', String(day.getDate())));
      refs.days.appendChild(cell);
    });

    refs.todayBtn.classList.toggle('is-done', doneToday);
    refs.todayBtn.setAttribute('aria-pressed', doneToday ? 'true' : 'false');
    refs.todayBtn.textContent = doneToday
      ? '\u2713 Done today \u2014 tap to undo'
      : 'Mark done for today';
  }

  function render() {
    var today = startOfDay(new Date());
    todayEl.textContent = formatLong(today);

    cards = {};
    listEl.textContent = '';
    emptyEl.textContent = '';

    if (state.habits.length === 0) {
      var box = el('div', 'empty');
      box.appendChild(el('strong', null, 'No habits yet'));
      box.appendChild(el('span', null, 'Add one above to start tracking.'));
      emptyEl.appendChild(box);
      hintEl.hidden = true;
      return;
    }

    hintEl.hidden = false;
    state.habits.forEach(function (habit) {
      listEl.appendChild(buildCard(habit));
      updateCard(habit);
    });
  }

  /*
   * updateCard() rebuilds the day cells, so the button that was clicked is
   * replaced. Put keyboard focus back on the equivalent button afterwards.
   */
  function withFocusRestored(mutate) {
    var active = document.activeElement;
    var action = active && active.dataset ? active.dataset.action : null;
    var date = active && active.dataset ? active.dataset.date : null;
    var card = active && active.closest ? active.closest('[data-habit-id]') : null;
    var habitId = card ? card.dataset.habitId : null;

    mutate();

    if (!habitId || !action) return;
    var selector = '[data-habit-id="' + habitId + '"] [data-action="' + action + '"]' +
      (date ? '[data-date="' + date + '"]' : '');
    var next = document.querySelector(selector);
    if (next) next.focus();
  }

  /* ------------------------------------------------------------------ *
   * Events
   * ------------------------------------------------------------------ */

  formEl.addEventListener('submit', function (event) {
    event.preventDefault();
    var name = inputEl.value.trim();
    if (!name) {
