      render();
      inputEl.focus();
      return;
    }

    if (action === 'toggle-today') {
      withFocusRestored(function () {
        var todayKey = dateKey(startOfDay(new Date()));
        setDone(habit, todayKey, !habit.done[todayKey]);
        updateCard(habit);
      });
      return;
    }

    if (action === 'toggle-day') {
      withFocusRestored(function () {
